style.css:
@-moz-document domain("discord.com") {
/* Main app container */
    body {
        background: url('https://i.etsystatic.com/37926435/r/il/457862/4631709551/il_fullxfull.4631709551_9mzc.jpg') center/cover no-repeat fixed !important;
    }
    
    /* Make Discord content semi-transparent */
    div[class^="app-"] {
        background: rgba(0, 0, 0, 0.7) !important;
    }
    
    /* Left sidebar (server list) */
    nav[class^="wrapper-"] {
        background: rgba(0, 0, 0, 0.8) !important;
    }
    
    /* Server channels sidebar */
    div[class^="sidebar-"] {
        background: rgba(0, 0, 0, 0.6) !important;
    }
    
    /* Main chat area */
    div[class^="chat-"] {
        background: rgba(0, 0, 0, 0.5) !important;
    }
    
    /* Message input box */
    div[class*="channelTextArea-"] {
        background: rgba(30, 30, 30, 0.8) !important;
    }
    
    /* Member list */
    div[class^="members-"] {
        background: rgba(0, 0, 0, 0.6) !important;
    }
    
    /* Messages container */
    div[class^="messagesWrapper-"] {
        background: transparent !important;
    }
    
    /* Individual messages */
    div[class^="message-"] {
        background: transparent !important;
    }
    
    div[class^="message-"]:hover {
        background: rgba(50, 50, 50, 0.4) !important;
    }
    
    /* Channel header */
    div[class*="title-"] {
        background: rgba(0, 0, 0, 0.7) !important;
    }
    
    /* Improved text readability */
    div[class^="markup-"] {
        color: #ffffff !important;
        text-shadow: 0 0 3px rgba(0, 0, 0, 0.5) !important;
    }
    
    /* Scrollbar styling */
    ::-webkit-scrollbar {
        width: 8px !important;
    }
    
    ::-webkit-scrollbar-thumb {
        background: rgba(255, 255, 255, 0.1) !important;
        border-radius: 4px !important;
    }
    
    ::-webkit-scrollbar-track {
        background: rgba(0, 0, 0, 0.3) !important;
    }
    
    /* Channel names */
    div[class^="name-"] {
        color: #ffffff !important;
    }
    
    /* Buttons */
    button[class*="button-"] {
        background: rgba(50, 50, 50, 0.7) !important;
    }
    
    button[class*="button-"]:hover {
        background: rgba(70, 70, 70, 0.9) !important;
    }
    
    /* Mentioned messages */
    div[class*="mentioned-"] {
        background: rgba(250, 166, 26, 0.1) !important;
    }
    
    /* Make text input visible */
    div[class*="textArea-"] {
        background: rgba(0, 0, 0, 0.3) !important;
        color: #ffffff !important;
    }
    
    /* Fix attachments and embeds */
    div[class*="attachment-"],
    div[class*="embed-"] {
        background: rgba(30, 30, 30, 0.5) !important;
    }
}
